const thumbs=new Map();function thumbnail(d){if(d.blob?.type.startsWith('image/')){if(!thumbs.has(d.id))thumbs.set(d.id,URL.createObjectURL(d.blob));return `<img src="${thumbs.get(d.id)}" alt="" class="document-thumb">`}return `<span class="case-icon">${icon('review')}</span>`}
docRow=function(d){const c=state.cases.find(c=>c.id===d.caseId);if(filter.value&&filter.value!==d.status)return '';return `<div class="case-row doc-row">${thumbnail(d)}<div class="row-info"><strong>${esc(d.title)}</strong><small>${esc(c?.label)} <span>•</span> ${esc(d.type)}</small></div><span class="document-date">${esc(d.date)}</span><span class="badge ${d.status==='Approved'?'approved':''}"><span></span>${esc(d.status)}</span><button class="row-button" data-doc="${esc(d.id)}" aria-label="Open ${esc(d.title)}">${icon('arrow')}</button></div>`};
let calendarMonth=new Date();calendarMonth.setDate(1);
function attentionHTML(){const pending=state.docs.filter(d=>d.status==='Needs review'),overdue=state.tasks.filter(t=>!t.done&&t.due<today()),upcoming=state.tasks.filter(t=>!t.done&&t.due>=today()).sort((a,b)=>a.due.localeCompare(b.due));return `<div class="attention-card"><div class="card-heading"><span class="tiny-label">WORKSPACE ASSISTANT</span><span class="assistant-symbol">${icon('spark')}</span></div><h2>A clearer picture<br>of what comes next.</h2><p>Operational reminders from your sample records.</p><button data-attention="review"><span>${pending.length} document${pending.length!==1?'s':''} to review</span>${icon('arrow')}</button><button data-attention="tasks"><span>${overdue.length} overdue task${overdue.length!==1?'s':''}</span>${icon('arrow')}</button><small>Rules-based summary · No clinical advice</small></div><div class="upcoming-card"><div class="card-heading"><h2>Next on your list</h2><button class="text-link" data-attention="calendar">View calendar ↗</button></div>${[...overdue,...upcoming].slice(0,3).map(t=>`<button class="upcoming-row" data-attention="tasks"><span class="date-tile">${esc(t.due.slice(8))}<small>${esc(new Date(t.due+'T12:00:00').toLocaleString('en',{month:'short'}))}</small></span><div><strong>${esc(t.title)}</strong><small>${esc(state.cases.find(c=>c.id===t.caseId)?.label)} · ${t.due<today()?'Overdue':esc(t.due)}</small></div><span class="upcoming-dot"></span></button>`).join('')||'<div class="empty">Your list is clear. Add a follow-up task to plan the next step.</div>'}<button class="task-add" id="home-add-task">＋ Create a follow-up task</button></div>`}
function calendarHTML(){const year=calendarMonth.getFullYear(),month=calendarMonth.getMonth(),start=new Date(year,month,1).getDay(),days=new Date(year,month+1,0).getDate();const appointments=state.appointments||[];let cells='';for(let i=0;i<start;i++)cells+='<div class="calendar-cell outside"></div>';for(let d=1;d<=days;d++){const key=`${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,tasks=state.tasks.filter(t=>t.due===key),appts=appointments.filter(a=>a.date===key);cells+=`<div class="calendar-cell ${key===today()?'is-today':''}"><span class="day-number">${d}</span>${appts.map(a=>`<button class="calendar-event session" data-session="${esc(a.id)}">${esc(a.time)} ${esc(a.title)}</button>`).join('')}${tasks.map(t=>`<button class="calendar-event ${t.done?'complete':''}" data-attention="tasks">${esc(t.title)}</button>`).join('')}</div>`}return `<div class="panel-heading"><div><span class="tiny-label">PLAN YOUR WEEK</span><h2>${esc(calendarMonth.toLocaleString('en',{month:'long',year:'numeric'}))}</h2><p>Tasks and sample sessions. External calendars and reminders are not connected.</p></div><div class="calendar-controls"><button class="secondary" id="month-prev" aria-label="Previous month">‹</button><button class="secondary" id="month-now">Today</button><button class="secondary" id="month-next" aria-label="Next month">›</button><button class="primary" id="session-add">＋ Session</button></div></div><div class="calendar-week">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${cells}</div><div class="calendar-mobile-list"><h3>Sessions this month</h3>${appointments.filter(a=>a.date.startsWith(`${year}-${String(month+1).padStart(2,'0')}`)).sort((a,b)=>`${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`)).map(a=>`<button class="upcoming-row" data-session="${esc(a.id)}"><div><strong>${esc(a.title)}</strong><small>${esc(a.date)} · ${esc(a.time)} · ${esc(state.cases.find(c=>c.id===a.caseId)?.label)}</small></div></button>`).join('')||'<p class="muted">No sample sessions scheduled this month.</p>'}</div>`}
function insightsHTML(){const total=state.docs.length,approved=state.docs.filter(d=>d.status==='Approved').length,rate=total?Math.round(approved/total*100):0,done=state.tasks.filter(t=>t.done).length;return `<div class="insight-heading"><span class="tiny-label">A WORKSPACE IN FOCUS</span><h2>Know where things stand.</h2><p>Live counts from records in this browser. No clinical outcome scoring.</p></div><div class="insight-grid"><div class="insight-card"><h3>Document review completion</h3><div class="completion-ring" style="--completion:${rate}%"><span>${rate}%<small>${approved} of ${total} approved</small></span></div></div><div class="insight-card"><h3>Service mix</h3>${[...new Set(state.cases.map(c=>c.service))].map(s=>{const n=state.cases.filter(c=>c.service===s).length;return `<div class="service-meter"><span>${esc(s)}</span><strong>${n}</strong><div><i style="width:${state.cases.length?n/state.cases.length*100:0}%"></i></div></div>`}).join('')}</div><div class="insight-card"><h3>Task completion</h3><strong class="insight-number">${done}<span> / ${state.tasks.length}</span></strong><p>Completed follow-up tasks</p><div class="wide-meter"><i style="width:${state.tasks.length?done/state.tasks.length*100:0}%"></i></div></div><div class="insight-card"><h3>Program participation</h3><strong class="insight-number">${(state.enrollments||[]).length}</strong><p>Sample program enrollments across ${COMPANY_REFERENCE.programs.length} reference programs.</p><button class="secondary" data-attention="programs">Explore programs ↗</button></div></div>`}
const originalRender=render;render=function(){const desired=currentView,special=['calendar','insights'].includes(desired);if(special)currentView='overview';originalRender();currentView=desired;$('page-title').textContent=labels[desired]||'Overview';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===desired));document.querySelector('.hero').hidden=desired!=='overview';homeExtras.hidden=desired!=='overview';document.querySelector('.stats').hidden=!['overview','insights'].includes(desired);document.querySelector('.quick-actions').hidden=desired==='programs';extraPanel.hidden=!special;document.querySelector('.panel').hidden=special||desired==='programs';$('open-task-count').textContent=state.tasks.filter(t=>!t.done).length;filter.hidden=!['overview','review'].includes(desired);if(desired==='overview'){homeExtras.innerHTML=attentionHTML();$('home-add-task').onclick=()=>$('task-open').click();$('list-title').textContent='Recent documents';$('list-subtitle').textContent='Capture, organize, and review in one place.'}if(desired==='cases'){$('records').querySelectorAll('[data-capture-case]').forEach(b=>{const id=b.dataset.captureCase;b.insertAdjacentHTML('beforebegin',`<button class="secondary case-profile" data-case-profile="${esc(id)}">Open case</button>`)});}if(desired==='calendar'){extraPanel.innerHTML=calendarHTML();$('month-prev').onclick=()=>{calendarMonth.setMonth(calendarMonth.getMonth()-1);render()};$('month-next').onclick=()=>{calendarMonth.setMonth(calendarMonth.getMonth()+1);render()};$('month-now').onclick=()=>{calendarMonth=new Date();calendarMonth.setDate(1);render()};$('session-add').onclick=()=>openSession()}if(desired==='insights')extraPanel.innerHTML=insightsHTML();if(['overview','review'].includes(desired)&&!$('records').children.length)$('records').innerHTML='<div class="empty">No documents match this status.</div>';document.querySelector('header strong').textContent=labels[desired]};
document.addEventListener('click',e=>{const a=e.target.closest('[data-attention]'),c=e.target.closest('[data-case-profile]'),s=e.target.closest('[data-session]');if(a){currentView=a.dataset.attention;render()}if(c)openCase(c.dataset.caseProfile);if(s)openSession(s.dataset.session)});
function newDialog(id,html){const dialog=document.createElement('dialog');dialog.id=id;dialog.innerHTML=html;document.body.append(dialog);dialog.querySelectorAll('.close').forEach(b=>b.onclick=()=>dialog.close());return dialog}
const caseProfile=newDialog('case-profile-dialog','<div class="modal-heading"><div><span class="tiny-label">CASE WORKSPACE</span><h2 id="profile-title"></h2></div><button class="close" aria-label="Close case">×</button></div><div id="profile-content"></div>');
function openCase(id){const c=state.cases.find(c=>c.id===id),docs=state.docs.filter(d=>d.caseId===id),tasks=state.tasks.filter(t=>t.caseId===id),sessions=(state.appointments||[]).filter(a=>a.caseId===id);$('profile-title').textContent=c.label;$('profile-content').innerHTML=`<span class="age-tag">${esc(c.service)}</span><div class="case-summary-metrics"><div><strong>${docs.length}</strong><span>Documents</span></div><div><strong>${tasks.filter(t=>!t.done).length}</strong><span>Open tasks</span></div><div><strong>${sessions.length}</strong><span>Sessions</span></div></div><div class="profile-actions"><button class="primary" id="profile-upload">${icon('capture')} Capture document</button><button class="secondary" id="profile-note">Write a note</button></div><h3 class="profile-section">Documents</h3>${docs.map(d=>`<button class="profile-doc" data-profile-doc="${esc(d.id)}">${icon('review')}<span>${esc(d.title)}</span><span class="badge ${d.status==='Approved'?'approved':''}">${esc(d.status)}</span></button>`).join('')||'<p class="muted">No documents yet.</p>'}<h3 class="profile-section">Case timeline</h3><div class="timeline">${docs.flatMap(d=>(d.events||[]).map(event=>({title:d.title,event,date:d.date}))).sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<div><span class="timeline-dot"></span><strong>${esc(x.title)}</strong><p>${esc(x.event)}</p></div>`).join('')||'<p class="muted">The timeline begins when you add a document or note.</p>'}</div>`;$('profile-upload').onclick=()=>{caseProfile.close();openCapture(id)};$('profile-note').onclick=()=>{caseProfile.close();$('digital-open').click();$('digital-case').value=id};$('profile-content').querySelectorAll('[data-profile-doc]').forEach(b=>b.onclick=()=>{caseProfile.close();openDoc(b.dataset.profileDoc)});caseProfile.showModal()}
const sessionDialog=newDialog('session-dialog','<form id="session-form"><div class="modal-heading"><div><span class="tiny-label">PLAN A SESSION</span><h2>Make time for the next step.</h2></div><button class="close" type="button" aria-label="Close">×</button></div><p class="muted">Sample scheduling only. No invitations or reminders are sent.</p><label class="field">Case folder<select id="session-case" required></select></label><label class="field">Session title<input id="session-title" required maxlength="120" placeholder="e.g. Sample parent coaching session"></label><div class="form-grid"><label class="field">Date<input id="session-date" type="date" required></label><label class="field">Time<input id="session-time" type="time" required></label></div><label class="field">Location<select id="session-location"><option>In community</option><option>In home</option><option>Office</option><option>Virtual</option></select></label><div class="modal-actions"><button type="button" class="danger" id="session-delete">Delete session</button><button class="primary">Save session</button></div></form>');let editingSession;
function openSession(id){editingSession=id||null;$('session-form').reset();$('session-case').innerHTML=caseOptions();$('session-date').value=today();$('session-time').value='09:00';$('session-delete').hidden=!id;if(id){const a=state.appointments.find(a=>a.id===id);$('session-case').value=a.caseId;$('session-title').value=a.title;$('session-date').value=a.date;$('session-time').value=a.time;$('session-location').value=a.location}sessionDialog.showModal()}
$('session-form').onsubmit=async e=>{e.preventDefault();const title=$('session-title').value.trim();if(!title)return;state.appointments??=[];const a={id:editingSession||uid(),caseId:$('session-case').value,title,date:$('session-date').value,time:$('session-time').value,location:$('session-location').value};if(editingSession)state.appointments=state.appointments.map(x=>x.id===editingSession?a:x);else state.appointments.push(a);await persist();sessionDialog.close();toast('Sample session saved. No external notifications sent.')};$('session-delete').onclick=async()=>{if(!confirm('Delete this sample session?'))return;state.appointments=state.appointments.filter(a=>a.id!==editingSession);await persist();sessionDialog.close();toast('Sample session removed.')};
const commandDialog=newDialog('command-dialog',`<div class="command-input">${icon('search')}<input id="command-search" placeholder="Find a case, document, or action…" aria-label="Search the workspace"><button class="close" aria-label="Close search">×</button></div><div id="command-results"></div><div class="command-footer">Search this browser’s sample records <kbd>Esc</kbd> to close</div>`);
function commandResults(){const q=$('command-search').value.toLowerCase(),actions=[['capture','Capture a document'],['note','Write a digital note'],['task','Create a follow-up task'],['calendar','Open calendar'],['programs','Explore programs'],['insights','View insights']];$('command-results').innerHTML=actions.filter(x=>x[1].toLowerCase().includes(q)).map(x=>`<button data-command="${x[0]}">${icon(x[0])}<span>${x[1]}</span><small>Action</small></button>`).join('')+state.cases.filter(c=>c.label.toLowerCase().includes(q)).slice(0,6).map(c=>`<button data-command-case="${esc(c.id)}">${icon('cases')}<span>${esc(c.label)}</span><small>${esc(c.service)}</small></button>`).join('')+state.docs.filter(d=>d.title.toLowerCase().includes(q)).slice(0,6).map(d=>`<button data-command-doc="${esc(d.id)}">${icon('review')}<span>${esc(d.title)}</span><small>Document</small></button>`).join('');if(!$('command-results').children.length)$('command-results').innerHTML='<div class="empty">No matches. Try a case label or document title.</div>'}
$('command-open').onclick=()=>{if(!state)return;$('command-search').value='';commandResults();commandDialog.showModal();$('command-search').focus()};$('command-search').oninput=commandResults;$('command-results').onclick=e=>{const b=e.target.closest('button');if(!b)return;commandDialog.close();if(b.dataset.commandCase)openCase(b.dataset.commandCase);else if(b.dataset.commandDoc)openDoc(b.dataset.commandDoc);else if(b.dataset.command==='capture')openCapture();else if(b.dataset.command==='note')$('digital-open').click();else if(b.dataset.command==='task')$('task-open').click();else{currentView=b.dataset.command;render()}};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();if(commandDialog.open)commandDialog.close();else $('command-open').click()}});
let theme='light';try{theme=localStorage.getItem('eero-theme')||'light'}catch{}document.documentElement.dataset.theme=theme;$('theme-toggle').onclick=()=>{theme=theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;try{localStorage.setItem('eero-theme',theme)}catch{}};
