const drop=document.createElement('div');drop.className='drop-zone';drop.tabIndex=0;drop.setAttribute('role','button');drop.setAttribute('aria-label','Choose files or drop documents');drop.innerHTML=icon('capture')+'<strong>Drop photos or PDFs here</strong><small>Or tap to browse · 15 MB per file</small>';document.querySelector('.capture-options').after(drop);drop.onclick=()=>$('files').click();drop.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('files').click()}};drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');chooseFiles(e.dataTransfer.files)};
const baseChoose=chooseFiles;let selectedUrls=[];chooseFiles=async function(files){await baseChoose(files);selectedUrls.forEach(x=>URL.revokeObjectURL(x));selectedUrls=[];$('selected-files').innerHTML=selected.length?selected.map((f,i)=>{let img=icon('review');if(f.type.startsWith('image/')){const url=URL.createObjectURL(f);selectedUrls.push(url);img=`<img src="${url}" alt="Selected photo ${i+1}">`}return `<div class="selected-file">${img}<span><strong>${esc(f.name)}</strong><small>${(f.size/1024/1024).toFixed(1)} MB</small></span><button type="button" data-remove-file="${i}" aria-label="Remove ${esc(f.name)}">×</button></div>`}).join(''):'No documents selected.'};$('selected-files').onclick=e=>{const b=e.target.closest('[data-remove-file]');if(b){selected.splice(Number(b.dataset.removeFile),1);chooseFiles([])}};
const baseOpenCapture=openCapture;openCapture=function(caseId){selectedUrls.forEach(x=>URL.revokeObjectURL(x));selectedUrls=[];baseOpenCapture(caseId)};
$('export-open').onclick=()=>{const data={exportedAt:new Date().toISOString(),prototype:true,cases:state.cases,documents:state.docs.map(({blob,...d})=>({...d,originalFileIncluded:false})),tasks:state.tasks,enrollments:state.enrollments||[],appointments:state.appointments||[]};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='eero-workspace-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Workspace record details exported. File attachments are excluded.')};
